const response = JSON.parse($input.first().json.message.content);
const rss = $('Loop Over Items').item.json;

if (!response.drug_name) {
  return [];  // Skip non-drug-specific alerts
}

return [{
  json: {
    source: 'FDA',
    alert_type: response.alert_type || 'safety_communication',
    severity: response.severity || null,
    drug_name: response.drug_name,
    drug_name_normalized: response.drug_name_normalized || response.drug_name.toLowerCase().replace(/[^a-z0-9]/g, ''),
    drug_name_aliases: response.drug_name_aliases || [],
    summary: response.summary || rss.title,
    full_text: rss.content || rss.contentSnippet,
    affected_lots: response.affected_lots || [],
    affected_countries: response.affected_countries || [],
    recommended_action: response.recommended_action || null,
    url: rss.link,
    published_date: rss.pubDate ? new Date(rss.pubDate).toISOString().split('T')[0] : new Date().toISOString().split('T')[0],
    extraction_confidence: response.extraction_confidence || 0.7
  }
}];
